import { useEffect, useMemo, useState } from "react";
import PageHeader from "../../../components/shared/PageHeader";
import Badge from "../../../components/shared/Badge";
import DataTable from "../../../components/shared/DataTable";
import { useToast } from "../../../context/ToastContext";
import { useAuth } from "../../../context/AuthContext";
import { donorKycApi } from "../../../services/api";

const API_BASE = process.env.REACT_APP_API_URL || "http://localhost:5000";

const statusType = (status) => {
  const normalized = String(status || "").toUpperCase();
  if (normalized === "APPROVED") return "green";
  if (normalized === "REJECTED") return "red";
  return "yellow";
};

const short = (value) => {
  const text = String(value || "");
  return text.length > 16 ? `${text.slice(0, 16)}...` : text;
};

const Modal = ({ open, title, status, note, setNote, onCancel, onConfirm, pending }) => {
  if (!open) return null;
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 70, display: "grid", placeItems: "center", background: "rgba(5,8,16,0.66)" }}>
      <div style={{ width: "min(560px, calc(100vw - 32px))", padding: 22, borderRadius: 16, background: "var(--bg-card)", border: "1px solid var(--border)", boxShadow: "var(--shadow)" }}>
        <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 6 }}>{title}</div>
        <div style={{ color: "var(--text-3)", marginBottom: 12 }}>Decision: {status}</div>
        <div className="form-group" style={{ marginBottom: 16 }}>
          <label>Review note</label>
          <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={4} placeholder="Optional approval or rejection note" />
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 10 }}>
          <button className="btn btn-secondary" onClick={onCancel} disabled={pending}>Cancel</button>
          <button className="btn btn-primary" onClick={onConfirm} disabled={pending}>{pending ? "Saving..." : status}</button>
        </div>
      </div>
    </div>
  );
};

const DocPreview = ({ items }) => {
  const docs = Array.isArray(items) ? items : [];
  if (!docs.length) return <span className="text-dim">None</span>;
  return (
    <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
      {docs.map((doc) => (
        <a key={doc.imageId || doc.fileUrl} href={`${API_BASE}${doc.fileUrl}`} target="_blank" rel="noreferrer" title={doc.fileName || doc.imageId}>
          <img src={`${API_BASE}${doc.fileUrl}`} alt={doc.fileName || doc.imageId} style={{ width: 46, height: 46, objectFit: "cover", borderRadius: 10, border: "1px solid var(--border)" }} />
        </a>
      ))}
    </div>
  );
};

const mergeDocs = (row) => [
  ...(row?.documents?.panFront || []),
  ...(row?.documents?.panBack || []),
  ...(row?.documents?.aadhaarFront || []),
  ...(row?.documents?.aadhaarBack || []),
];

export default function DonorApprovalsPage() {
  const toast = useToast();
  const { user } = useAuth();
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(false);
  const [reviewModal, setReviewModal] = useState({ open: false, donorId: "", status: "APPROVED" });
  const [reviewNote, setReviewNote] = useState("");
  const [saving, setSaving] = useState(false);
  const adminCert = String(user?.userCert || "").trim();

  const pendingCount = useMemo(() => rows.filter((row) => String(row.status || "").toUpperCase() === "PENDING").length, [rows]);

  const load = async () => {
    if (!adminCert) return;
    setLoading(true);
    try {
      const res = await donorKycApi.list({ userCert: adminCert });
      setRows(Array.isArray(res?.data) ? res.data : []);
    } catch (error) {
      toast(error?.response?.data?.error || error.message || "Failed to load donor approvals", "error");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, [adminCert]);

  const openReview = (donorId, status) => {
    setReviewModal({ open: true, donorId, status });
    setReviewNote("");
  };

  const submitReview = async () => {
    if (!reviewModal.donorId) return;
    setSaving(true);
    try {
      await donorKycApi.review({
        donorId: reviewModal.donorId,
        reviewedBy: adminCert,
        status: reviewModal.status,
        reviewNote,
      });
      toast(`Donor ${reviewModal.status.toLowerCase()} successfully`, "success");
      setReviewModal({ open: false, donorId: "", status: "APPROVED" });
      await load();
    } catch (error) {
      toast(error?.response?.data?.error || error.message || "Failed to review donor", "error");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div>
      <Modal
        open={reviewModal.open}
        title="Review donor KYC"
        status={reviewModal.status}
        note={reviewNote}
        setNote={setReviewNote}
        onCancel={() => setReviewModal({ open: false, donorId: "", status: "APPROVED" })}
        onConfirm={submitReview}
        pending={saving}
      />

      <PageHeader title="Donor Approvals" desc="Review PAN and Aadhaar submissions before donors can top up or donate" />

      <div className="stats-row" style={{ gridTemplateColumns: "repeat(3,1fr)", marginBottom: 16 }}>
        <div className="stat-card gold">
          <div className="stat-label">Total Requests</div>
          <div className="stat-value gold">{rows.length}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">Pending Review</div>
          <div className="stat-value">{pendingCount}</div>
        </div>
        <div className="stat-card">
          <div className="stat-label">Reviewer</div>
          <div className="stat-value">{adminCert || "—"}</div>
        </div>
      </div>

      <div className="card">
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 16 }}>
          <div>
            <div className="card-title">KYC Queue</div>
            <div className="card-sub">Approve only after you verify the uploaded document images.</div>
          </div>
          <button className="btn btn-primary" onClick={load} disabled={loading}>{loading ? "Refreshing..." : "Refresh"}</button>
        </div>

        <DataTable
          columns={[
            { key: "donorId", label: "Donor ID", mono: true },
            { key: "panNumber", label: "PAN", render: (r) => short(r.panNumber) },
            { key: "aadhaarNumber", label: "Aadhaar", render: (r) => short(r.aadhaarNumber) },
            { key: "status", label: "Status", render: (r) => <Badge type={statusType(r.status)}>{r.status}</Badge> },
            { key: "submittedAt", label: "Submitted", mono: true },
            { key: "reviewedBy", label: "Reviewed By", mono: true },
            { key: "reviewNote", label: "Review Note" },
            { key: "documents", label: "Documents", render: (r) => <DocPreview items={mergeDocs(r)} /> },
            {
              key: "actions",
              label: "Actions",
              render: (r) => (
                <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                  <button className="btn btn-primary" onClick={() => openReview(r.donorId, "APPROVED")} disabled={String(r.status || "").toUpperCase() === "APPROVED"}>Approve</button>
                  <button className="btn btn-secondary" onClick={() => openReview(r.donorId, "REJECTED")} disabled={String(r.status || "").toUpperCase() === "REJECTED"}>Reject</button>
                </div>
              ),
            },
          ]}
          data={rows}
          emptyText="No donor KYC submissions found"
        />
      </div>
    </div>
  );
}
